% Math macros for the ChowKnopf blueprint — consolidated for hgraph/KaTeX.

% --- from macros/common.tex ---
\newtheorem{theorem}{Theorem}[chapter]
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}

\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}
\newtheorem{example}[theorem]{Example}
\newtheorem{notation}[theorem]{Notation}
\newtheorem{convention}[theorem]{Convention}
\newtheorem{conjecture}[theorem]{Conjecture}

\newcommand{\Ric}{\operatorname{Ric}}
\newcommand{\Rc}{\operatorname{Rc}}
\newcommand{\Rm}{\operatorname{Rm}}
\newcommand{\Lie}{\mathcal{L}}
\newcommand{\divergence}{\operatorname{div}}
\newcommand{\ad}{\operatorname{ad}}
\newcommand{\Vol}{\operatorname{Vol}}
\newcommand{\Hess}{\operatorname{Hess}}
\newcommand{\M}{\mathcal{M}}
\newcommand{\N}{\mathcal{N}}
\newcommand{\G}{\mathcal{G}}
\newcommand{\Hcal}{\mathcal{H}}
\newcommand{\R}{\mathbb{R}}
\newcommand{\SU}{\mathrm{SU}}
\newcommand{\SO}{\mathrm{SO}}
\newcommand{\SL}{\mathrm{SL}}
\newcommand{\nil}{\mathrm{nil}}
\newcommand{\sol}{\mathrm{sol}}
\newcommand{\Isom}{\operatorname{Isom}}
\newcommand{\Ogroup}{\operatorname{O}}
\newcommand{\diam}{\operatorname{diam}}
\newcommand{\tr}{\operatorname{tr}}
\newcommand{\sgn}{\operatorname{sgn}}
\newcommand{\dd}{\,\mathrm{d}}
\newcommand{\symtensor}{\mathbin{\odot}}
\newcommand{\sect}{\operatorname{sect}}
\newcommand{\inj}{\operatorname{inj}}

% Horizon metadata is parsed into the DAG and hidden in print output.
\providecommand{\dcref}[1]{}
